'use strict';
const AiMakingDesk=(()=>{
 const P=ProductionClient,L=AiMakingDeskLogic,client=new P.Client();
 const state={owner:null,project:null,projects:[],assets:[],view:'make',filter:'all',tab:'decision',selected:null,checked:new Set(),time:0,zoom:1,busy:false,run:null,job:null,message:'',modal:null,styleId:null,edited:{},generation:0};
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const root=()=>document.querySelector('.ai-workbench-desk');
 const cards=()=>state.project?.cards||[];
 const asset=id=>state.assets.find(a=>a.id===id);
 const styles=()=>state.assets.filter(a=>a.kind==='style'&&a.metadata?.technical_status==='passed');
 const images=()=>state.assets.filter(a=>a.kind==='image');
 const current=()=>cards().find(c=>c.id===state.selected)||cards()[0];
 const source=()=>asset(state.project?.source?.asset_id);
 const total=()=>L.duration(state.project,source());
 const chosen=c=>asset(c?.style?.asset_id);
 const selectedIds=()=>P.selection(state.project,[...state.checked]);
 const title=()=>state.project?.name||S.p?.name||'新制作项目';
 const savedKey=()=>`ai-production-project:${state.owner}`;
 function note(text){state.message=text;const el=root()?.querySelector('.notice');if(el){el.textContent=text;el.classList.add('show');clearTimeout(note.timer);note.timer=setTimeout(()=>el?.classList.remove('show'),6500);}}
 function modal(title,body){state.modal={title,body};const el=root()?.querySelector('.modal-backdrop');if(el){el.hidden=false;el.querySelector('#desk-modal-body').innerHTML=`<div class="eyebrow">AI WORKBENCH</div><h2>${E(title)}</h2>${body}`;}}
 function closeModal(){state.modal=null;const el=root()?.querySelector('.modal-backdrop');if(el)el.hidden=true;}
 function fail(error){note(error.message||String(error));}
 function applyProject(project){state.project=project;state.checked=new Set(P.selection(project,[...state.checked]));if(!cards().some(c=>c.id===state.selected)){const pick=cards().find(c=>c.decision==='broll')||cards()[0];state.selected=pick?.id||null;state.time=pick?pick.start+.4:0;}if(project)localStorage.setItem(savedKey(),project.id);}
 function status(c){return L.status(c);}
 function cardHTML(c){return `<article class="decision ${c.id===state.selected?'selected':''}" data-desk-select="${E(c.id)}" tabindex="0" aria-label="定位 ${L.time(c.start)} ${E(c.text)}"><div class="decision-top"><label class="check-wrap" title="加入批量选择"><input type="checkbox" data-desk-check="${E(c.id)}" ${state.checked.has(c.id)?'checked':''}><span></span></label><span class="timecode">${L.time(c.start)} — ${L.time(c.end)}</span><span class="status ${c.decision==='gap'&&c.status!=='rejected'?'missing':c.status==='approved'?'accepted':c.decision==='keep'?'kept':''}">${status(c)}</span></div><p class="decision-quote">${E(c.text)}</p><div class="decision-foot"><span class="tiny-mark ${c.decision==='gap'?'missing':c.decision==='keep'?'keep':''}"></span><span>${E(c.decision==='broll'?chosen(c)?.name||'待选样式':c.decision==='gap'?'等待合适素材':'原镜头保留')}</span><span class="chevron">↗</span></div></article>`;}
 function queue(){const shown=L.filter(cards(),state.filter),selected=selectedIds().length;return `<aside class="queue panel"><div class="queue-heading"><div class="eyebrow">01 / AGENT REVIEW</div><h2>逐段判断<span class="count">${String(cards().length).padStart(2,'0')}</span></h2><p>先决定哪里该出现画面，再处理每段的内容和节奏。</p></div><div class="filter-row">${[['all','全部'],['pending','待判断'],['missing','缺口'],['done','已处理']].map(([id,name])=>`<button class="filter ${state.filter===id?'active':''}" data-desk-filter="${id}">${name}</button>`).join('')}</div><div class="queue-select"><label><input type="checkbox" data-desk-check-all ${shown.length&&shown.every(c=>state.checked.has(c.id))?'checked':''}> 选择当前列表</label><span>${shown.length} 个判断</span></div><div class="decision-list">${shown.map(cardHTML).join('')||'<div class="desk-note">当前筛选没有片段</div>'}</div><div class="batch-area ${selected?'has-selection':''}"><div class="batch-head"><span>${selected?`已选择 <b>${selected}</b> 段`:'批量审看'}</span><button data-desk-action="clear" ${selected?'':'disabled'}>清空</button></div><div class="batch-buttons"><button data-desk-action="reject" ${selected?'':'disabled'}>保留原镜头</button><button class="strong" data-desk-action="approve" ${selected?'':'disabled'}>采纳可确认建议</button></div><small>缺口和未通过预览的建议会留待处理。</small></div></aside>`;}
 function stage(){const c=current();const url=P.blob(source()?.blob_hash),aspect=source()?.metadata?.media,ratio=aspect?.width&&aspect?.height?`${aspect.width}:${aspect.height}`:'原画幅';return `<main class="stage"><div class="stage-head"><div><div class="eyebrow">PROJECT / ${state.project?.id?.slice(0,6)||'NEW'}</div><h1>${E(title())}<span> · 口播视频</span></h1></div><div class="stage-actions"><span class="draft-badge"><i></i>${state.busy?'正在处理':state.project?`已保存 · v${state.project.revision}`:'等待导入'}</span><button class="button ghost" data-desk-action="generate">Agent 重新判断</button><button class="button primary" data-desk-action="review">查看审片清单　↗</button></div></div><div class="stage-main"><div class="context-line"><span>画面预览</span><span class="dot-sep">/</span><b>${E(ratio)}</b><span class="context-right">${c?`当前片段 ${L.time(c.start)}–${L.time(c.end)}`:''}　<span class="preview-label">${L.activeCard(cards(),state.time)?.preview_url?'实际预览':'原片 / 待生成预览'}</span></span></div><div class="preview-space"><div class="preview-surround"><div class="preview-frame">${url?`<video id="desk-source-video" playsinline preload="metadata" src="${E(url)}" aria-label="原口播预览"></video>`:'<div class="preview-placeholder">还没有关联视频；可以从当前项目导入口播</div>'}<div id="stage-overlay"></div><div id="subtitle" class="subtitle"></div></div><div class="frame-shadow"></div></div><div class="stage-side-note"><span class="side-note-line"></span><span>REAL PROJECT PREVIEW<br>ORIGINAL AUDIO</span></div></div><div class="player"><button class="round-control" data-desk-action="back" title="后退一秒">↶</button><button class="play-control" data-desk-action="play" aria-label="播放或暂停">▶</button><button class="round-control" data-desk-action="forward" title="前进一秒">↷</button><span class="player-time" id="desk-player-time">${L.time(state.time)}</span><span class="player-total">/ ${L.time(total())}</span><span class="player-spacer"></span><button class="sound-control" data-desk-action="mute">♫ 音频开</button><span class="ratio-control">${E(ratio)}</span></div><div class="transcript-strip"><div class="transcript-marker">此处口播</div><p>“${E(c?.text||'Agent 尚未生成逐段判断')}”</p><button data-desk-tab="decision">查看判断依据 ↗</button></div></div></main>`;}
 function evidence(c){return `<div class="evidence"><div class="section-heading">判断所用证据 <span>↗</span></div>${(c.evidence||[]).map(id=>`<div class="evidence-item"><span class="evidence-icon">◇</span><div><strong>${E(id.split(':')[0])}</strong><p>${E(L.reference(id,state.project?.segments||[],styles()))}</p></div></div>`).join('')}${(c.alternatives||[]).map(a=>`<div class="evidence-item"><span class="evidence-icon">↗</span><div><strong>${E(asset(a.style_id)?.name||a.style_id)}</strong><p>${E(a.reason)}</p></div></div>`).join('')}${(c.missing||[]).map(m=>`<div class="evidence-item"><span class="evidence-icon">＋</span><div><strong>还缺</strong><p>${E(m)}</p></div></div>`).join('')}</div>`;}
 function fieldsHTML(c,st){const schema=P.fields(st);return schema.map(f=>{const value=Object.hasOwn(state.edited,f.key)?state.edited[f.key]:c.fields?.[f.key]??'';return `<label class="desk-field">${E(f.label||f.key)}${f.type==='image'?`<select data-desk-field="${E(f.key)}" data-desk-type="image"><option value="">保留样式原图</option>${images().map(a=>`<option value="${E(a.id)}" ${value?.asset_id===a.id?'selected':''}>${E(a.name)} · v${a.revision}</option>`).join('')}</select>`:`<input data-desk-field="${E(f.key)}" value="${E(value)}" ${f.max_length?`maxlength="${Number(f.max_length)}"`:''} placeholder="${E(f.default||'填入替换文字')}">`}</label>`;}).join('');}
 function inspector(){
  const c=current();
  if(!c)return `<aside class="inspector panel"><div class="inspector-head"><div class="eyebrow">02 / THE DECISION</div><h2>这一段怎么处理</h2></div><div class="inspector-scroll"><p class="desk-note">导入当前口播，让 Agent 为项目生成判断草稿。</p><button class="button primary" data-desk-action="generate">导入并判断</button></div></aside>`;
  const st=asset(state.styleId)||chosen(c),num=String(cards().indexOf(c)+1).padStart(2,'0');
  const reason=`<div class="rationale"><span class="small-label">AGENT 的建议 <i class="tiny-mark ${c.decision==='gap'?'missing':c.decision==='keep'?'keep':''}"></i></span><h3>${E(c.decision==='gap'?'先补素材，再决定':c.decision==='keep'?'这里保留口播':`此处使用「${chosen(c)?.name||'B-roll'}」`)}</h3><p>${E(c.reason)}</p><div class="reason-foot"><span>${c.render_report?.layout?.status==='passed'?'版式：通过':c.render_report?.layout?.status==='needs_revision'?'版式：需调整':'预览：待核对'}</span><span>状态：${status(c)}</span></div></div>${evidence(c)}${c.render_report?.layout?.issues?.length?`<div class="timing-warning">${c.render_report.layout.issues.map(i=>E(i.message||JSON.stringify(i))).join('；')}</div>`:''}`;
  const choices=`<div class="edit-section"><div class="section-heading">选择一种画面</div><button class="style-choice original ${c.decision==='keep'?'active':''}" data-desk-action="reject-current"><span class="original-icon">▣</span><span><strong>保留原口播</strong><small>这一段不叠加 B-roll</small></span><span>↗</span></button>${styles().map(a=>`<button class="style-choice ${st?.id===a.id?'active':''}" data-desk-style="${E(a.id)}"><span class="style-swatch">${a.metadata?.poster_hash?`<img src="${P.blob(a.metadata.poster_hash)}" alt="">`:'◇'}</span><span><strong>${E(a.name)} <em>v${a.revision}</em></strong><small>${E(a.metadata?.purpose||a.metadata?.description||'共享库实际样式')}</small></span><span>↗</span></button>`).join('')}</div>`;
  const edit=`${choices}<div class="edit-section"><div class="section-heading">可替换元素</div>${st?fieldsHTML(c,st):'<p class="desk-note">选择共享样式后填写标题和图片。</p>'}<button class="button ghost" data-desk-action="images">批量导入图片</button> <button class="button ghost" data-desk-action="cases">导入复刻案例</button><p class="desk-note">图片和样式固定为共享资产版本。</p></div>${c.decision==='broll'?`<div class="edit-section"><div class="section-heading">入场与画幅</div><label class="desk-field">转场方式<select data-desk-effect="transition"><option value="cut" ${c.transition!=='dissolve'?'selected':''}>直切</option><option value="dissolve" ${c.transition==='dissolve'?'selected':''}>淡入淡出</option></select></label><label class="desk-field">画幅适配<select data-desk-effect="crop_mode"><option value="contain" ${c.crop_mode!=='cover'?'selected':''}>完整画面</option><option value="cover" ${c.crop_mode==='cover'?'selected':''}>铺满裁剪</option></select></label><p class="desk-note">在时间线上拖动片段或拉两端调整时长。改动写入项目并使旧预览失效。</p></div>`:''}`;
  return `<aside class="inspector panel"><div class="inspector-head"><div class="eyebrow">02 / THE DECISION</div><h2>这一段怎么处理<span>${num} / ${String(cards().length).padStart(2,'0')}</span></h2><div class="inspector-tabs"><button class="${state.tab==='decision'?'active':''}" data-desk-tab="decision">判断依据</button><button class="${state.tab==='edit'?'active':''}" data-desk-tab="edit">样式与动效</button></div></div><div class="inspector-scroll">${c.timing_adjusted&&!c.preview_url?'<div class="timing-warning">⚑ 覆盖时间已改变，预览失效。请重新核对口播和画面。</div>':''}${state.tab==='decision'?reason:edit}</div><div class="inspector-footer"><button class="button ghost" data-desk-action="reject-current">保留口播</button><button class="button primary" data-desk-action="${state.tab==='edit'?'save-style':c.decision==='broll'?'approve-current':'edit'}">${state.tab==='edit'?'保存替换':c.decision==='broll'?'采纳这一段':'挑选样式'}</button><small>${c.decision==='broll'&&!L.ready(c)?'先渲染预览并检查画面，才能采纳。':'改动会保存到当前项目。'}</small></div></aside>`;
 }
 function timeline(){const d=total(),marks=Array.from({length:Math.ceil(d/5)+1},(_,i)=>i*5).filter(n=>n<=d),overlays=cards().filter(c=>c.decision==='broll'&&c.status!=='rejected'||c.decision==='gap'&&c.status!=='rejected');return `<section class="timeline"><div class="timeline-heading"><div><span class="eyebrow">03 / EDITING DESK</span><h2>时间线 <span>口播始终是底片 · B-roll 叠在上方</span></h2></div><div class="timeline-tools"><button data-desk-action="back" title="后退一秒">↶</button><button data-desk-action="forward" title="前进一秒">↷</button><span class="tool-divider"></span><button data-desk-action="zoom-out" title="缩小">−</button><span>${Math.round(state.zoom*100)}%</span><button data-desk-action="zoom-in" title="放大">＋</button></div></div><div class="timeline-body"><div class="track-labels"><div class="ruler-label">时间 / 秒</div><div class="track-label proposed"><b>01</b><span>画面覆盖<small>建议的 B-roll</small></span></div><div class="track-label caption"><b>02</b><span>字幕<small>跟随口播</small></span></div><div class="track-label source"><b>03</b><span>原始口播<small>画面 + 声音</small></span></div></div><div class="timeline-scroll" id="desk-timeline-scroll"><div class="timeline-content" style="width:${Math.round(state.zoom*100)}%;min-width:${Math.round(850*state.zoom)}px"><div class="ruler" data-desk-ruler>${marks.map(n=>`<span class="ruler-tick" style="left:${n/d*100}%">${String(n).padStart(2,'0')}s</span>`).join('')}</div><div class="track overlay-track">${overlays.map(c=>`<div class="timeline-clip ${c.decision==='gap'?'missing':'suggested'} ${c.status==='approved'?'accepted':''} ${c.id===state.selected?'selected':''}" data-desk-clip="${E(c.id)}" style="left:${c.start/d*100}%;width:${(c.end-c.start)/d*100}%"><span class="trim left" data-desk-trim="left"></span><span class="clip-label">${E(c.decision==='gap'?'＋ 待补画面':chosen(c)?.name||'B-roll')}</span><span class="trim right" data-desk-trim="right"></span></div>`).join('')}</div><div class="track caption-track">${(state.project?.segments||[]).map(s=>`<div class="caption-block" data-desk-seek="${s.start}" style="left:${s.start/d*100}%;width:${(s.end-s.start)/d*100}%" title="${E(s.text)}"><span>${E(s.text)}</span></div>`).join('')}</div><div class="track source-track"><div class="source-clip"><div class="waveform">${Array.from({length:140},(_,i)=>`<i style="height:${12+Math.round((.4+.6*Math.abs(Math.sin(i*.63)+Math.sin(i*.17))*.5)*29)}px"></i>`).join('')}</div><span>${E(source()?.name||'原口播')}</span><span class="source-duration">${L.time(d)}</span></div></div><div class="playhead" id="desk-playhead" style="left:${state.time/d*100}%"><i></i></div></div></div></div><div class="timeline-tip"><span>✳</span>点建议定位；拖动 B-roll 片段或拉两端调整时间。时间码和效果保存到项目。<span class="tip-right">预览需重新生成后才能确认与渲染。</span></div></section>`;}
 function library(){return `<div class="alt-view"><div class="alt-intro"><div class="eyebrow">SHARED LIBRARY / 共享资产</div><h1>一次复刻，反复使用。</h1><p>这里显示独立资产库中已通过技术验证的样式。每次用于新口播，仍需审看实际替换画面。</p><button class="button primary" data-desk-view="make">返回项目制作 ↗</button> <button class="button ghost" data-desk-action="cases">导入已有复刻案例</button> <button class="button ghost" data-desk-action="images">批量导入图片</button></div><div class="library-grid">${styles().map(a=>`<article class="library-card"><div class="library-art">${a.metadata?.poster_hash?`<img src="${P.blob(a.metadata.poster_hash)}" alt="${E(a.name)}">`:'◇'}</div><div class="library-meta"><span>共享样式 · v${a.revision}</span><h2>${E(a.name)}</h2><p>${E(a.metadata?.purpose||a.metadata?.description||'技术验证已通过')}</p><button data-desk-use="${E(a.id)}">放到当前片段 ↗</button></div></article>`).join('')||'<p>共享库目前没有可用样式。</p>'}</div><div class="library-footer">已导入图片 ${images().length} 张 · 样式 ${styles().length} 个 · 与项目独立保存</div></div>`;}
 function renderView(){const r=root();if(!r)return;r.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-desk-view="make"><span class="brand-symbol">✳</span><span>AI <b>工作台</b></span></button><span class="top-divider"></span><div class="project-breadcrumb">制作项目 <span>／</span> <select id="desk-project-select" aria-label="选择制作项目">${(state.owner&&state.owner!=='standalone'?P.matchingProjects(state.owner,state.projects,state.assets):state.projects).map(p=>`<option value="${E(p.id)}" ${state.project?.id===p.id?'selected':''}>${E(p.name)}</option>`).join('')||`<option>${E(title())}</option>`}</select><button class="desk-new" data-desk-action="new-project" title="导入视频或创建制作项目">＋</button></div><nav class="top-nav"><button data-desk-view="research">参考研究</button><button data-desk-view="library" class="${state.view==='library'?'active':''}">共享样式</button><button data-desk-view="make" class="${state.view==='make'?'active':''}">项目制作</button></nav><div class="top-right"><span class="autosave">● ${state.busy?'正在处理':'本机已保存'}</span><button class="avatar" title="本机项目">L</button></div></header>${state.view==='library'?library():`<div class="work-area">${queue()}${stage()}${inspector()}</div>${timeline()}`}<div class="notice" role="status">${E(state.message)}</div><div class="modal-backdrop" hidden><div class="modal"><button class="modal-close" data-desk-action="close">×</button><div id="desk-modal-body"></div></div></div><input id="desk-images" type="file" accept="image/*" multiple hidden></div>`;if(state.modal)modal(state.modal.title,state.modal.body);if(state.view==='make')attachVideo();}
 function attachVideo(){const video=root()?.querySelector('#desk-source-video');if(!video)return;const start=state.time;video.addEventListener('loadedmetadata',()=>{video.currentTime=Math.min(start,video.duration||start);updatePlayback();},{once:true});video.addEventListener('timeupdate',()=>{state.time=video.currentTime;updatePlayback();});video.addEventListener('play',updatePlayback);video.addEventListener('pause',updatePlayback);video.addEventListener('error',()=>note('原视频暂时无法播放；项目草稿与样式仍可审看。'));if(video.readyState>=1)video.currentTime=start;updatePlayback();}
 function updatePlayback(){const r=root(),v=r?.querySelector('#desk-source-video'),active=L.activeCard(cards(),state.time),overlay=r?.querySelector('#stage-overlay');if(!r)return;const ph=r.querySelector('#desk-playhead');if(ph)ph.style.left=`${Math.min(100,state.time/total()*100)}%`;const clock=r.querySelector('#desk-player-time');if(clock)clock.textContent=L.time(state.time);const play=r.querySelector('.play-control');if(play)play.textContent=v&&!v.paused?'Ⅱ':'▶';const seg=(state.project?.segments||[]).find(s=>s.start<=state.time&&state.time<s.end);const subtitle=r.querySelector('#subtitle');if(subtitle)subtitle.textContent=seg?.text||'';if(overlay){const preview=active&&P.media(active.preview_url);if(overlay.dataset.preview!==preview){overlay.dataset.preview=preview||'';overlay.innerHTML=preview?`<video id="desk-overlay-video" muted playsinline preload="metadata" src="${E(preview)}"></video>`:active?'<div class="preview-placeholder">样式已选，当前替换尚未生成实际预览</div>':'';}const clip=r.querySelector('#desk-overlay-video');if(clip&&v){const at=Math.max(0,state.time-active.start);if(clip.readyState>=1&&Math.abs(clip.currentTime-at)>.12)clip.currentTime=at;if(!v.paused&&clip.paused)clip.play().catch(()=>{});if(v.paused&&!clip.paused)clip.pause();}}}
 async function hydrate(force=false){const owner=S.p?.id||'standalone';if(!force&&state.owner===owner&&state.project){renderView();return;}state.owner=owner;const token=++state.generation;state.busy=true;renderView();try{const library=await client.library();if(token!==state.generation)return;state.projects=library.projects;state.assets=library.assets;const choice=P.chooseProject(owner,library.projects,library.assets,localStorage.getItem(savedKey()));if(choice){const response=await client.request(`/projects/${choice.id}`);if(token!==state.generation)return;applyProject(response.project);const runId=response.project.runs?.at(-1);if(runId)try{state.run=(await client.request(`/runs/${runId}`)).run;}catch{state.run=null;}}else applyProject(null);state.message=choice?'':'当前视频还没有制作项目。点击“Agent 重新判断”导入并生成。';}catch(error){state.message=error.message;}finally{if(token===state.generation){state.busy=false;renderView();}}}
 async function batch(action,ids,extra={}){if(state.busy||!state.project)return;state.busy=true;renderView();try{const result=await client.request(`/projects/${state.project.id}/batch`,P.batchBody(state.project,ids,action,extra));applyProject(result.project);state.edited={};state.styleId=null;state.message='改动已保存到制作项目；如已修改 B-roll，请重新生成实际预览。';}finally{state.busy=false;renderView();}}
 async function loadCurrent(){const response=await client.request(`/projects/${state.project.id}`);applyProject(response.project);renderView();}
 async function run(resume=null){if(state.busy)return;state.busy=true;renderView();try{if(!state.project){if(!S.p)throw new Error('请先选择一个口播视频项目。');const response=await client.request('/workbench-import',{project_id:S.p.id});state.projects.unshift(response.project);applyProject(response.project);}const response=await client.request(`/projects/${state.project.id}/run`,resume?{resume_run_id:resume}:{});state.run=response.run;state.message='Agent 正在查看原片、检索共享库并比较候选…';poll('run',response.run.id,state.project.id);}finally{state.busy=false;renderView();}}
 async function job(kind,ids=[]){if(state.busy||!state.project)throw new Error('先导入口播并生成草稿。');if(kind==='preview'){ids=P.selection(state.project,ids).filter(id=>cards().some(c=>c.id===id&&c.decision==='broll'));if(!ids.length)throw new Error('请选择需要预览的 B-roll 片段。');}state.busy=true;renderView();try{const response=await client.request(`/projects/${state.project.id}/${kind}`,kind==='preview'?{card_ids:ids}:{});state.job={...response.job,kind};state.message=kind==='preview'?'正在生成实际替换预览…':'正在合成已确认的口播视频…';poll('job',response.job.id,state.project.id);}finally{state.busy=false;renderView();}}
 async function poll(kind,id,projectId){try{const result=await client.request(`/${kind==='run'?'runs':'jobs'}/${id}`);if(state.project?.id!==projectId||S.view!=='ai-making')return;const value=result[kind];state[kind]=value;if(P.pending(value.status)){setTimeout(()=>poll(kind,id,projectId),1400);return;}await loadCurrent();state.message=value.error||`${kind==='run'?'Agent 判断草稿':'实际输出'}已保存。`;renderView();}catch(error){fail(error);}}
 async function doApprove(ids){const decision=L.approveSelection(state.project,ids);if(!decision.eligible.length){note('所选片段还没有可确认的实际预览；先预览 B-roll，缺口可换样式或保留口播。');return;}await batch('approve',decision.eligible);state.message=`已确认 ${decision.eligible.length} 段；${decision.skipped.length} 段仍待补齐或预览。`;note(state.message);}
 async function saveStyle(){const c=current(),st=asset(state.styleId)||chosen(c);if(!st)throw new Error('先选择共享库中的样式。');const fields={...state.edited};if(state.styleId&&state.styleId!==c.style?.asset_id)await batch('replace',[c.id],{style_id:st.id,fields});else if(Object.keys(fields).length)await batch('replace',[c.id],{fields});else throw new Error('先选择另一种样式或修改可替换元素。');state.tab='edit';renderView();}
 async function effect(field,value){const c=current();if(!c||c.decision!=='broll')return;await batch('effect',[c.id],{crop_mode:field==='crop_mode'?value:c.crop_mode||'contain',transition:field==='transition'?value:c.transition||'cut'});}
 async function uploadImages(files){if(!files?.length)return;state.busy=true;renderView();let count=0;try{for(const file of files){await client.upload(file);count++;}state.assets=(await client.request('/assets')).assets||[];state.message=`${count} 张图片已写入共享资产库。`;}finally{state.busy=false;renderView();}}
 async function cases(){const response=await client.request('/cases');modal('导入已有复刻成果',`<p>导入会执行实际替换与技术验证，通过后样式进入独立共享库。</p><div class="stack">${(response.cases||[]).map(c=>`<button class="button" data-desk-case="${E(c.case_id||c.id)}">${E(c.name)}</button>`).join('')||'目前没有可导入的案例。'}</div>`);}
 async function importCase(id){state.busy=true;renderView();try{await client.request('/cases/import',{case_id:id});state.assets=(await client.request('/assets')).assets||[];closeModal();state.message='样式已写入共享库，可以用于当前或其他项目。';}finally{state.busy=false;renderView();}}
 function newProject(){modal("新建制作项目",`<p>当前视频：${E(S.p?.name||"未选择")}。可将它的真实口播和原片导入 Agent，也可以先去视频库添加其他视频。</p><div class="modal-actions"><button class="button primary" data-desk-action="import-current">用当前视频建立项目</button><button class="button ghost" data-desk-action="go-import">打开视频库 ↗</button></div><p>如果当前视频还没有字幕，先在“拉片”执行转文字，再回来生成逐段草稿。</p>`);}
 async function importCurrent(){if(!S.p)throw new Error("请先从视频库选择口播。");const response=await client.request("/workbench-import",{project_id:S.p.id});state.projects.unshift(response.project);applyProject(response.project);closeModal();state.message="当前口播已导入，请运行 Agent 形成草稿。";renderView();}
 function review(){const counts={draft:cards().filter(c=>c.status==='draft').length,gap:cards().filter(c=>c.decision==='gap'&&c.status!=='rejected').length,done:cards().filter(c=>c.status==='approved'||c.status==='rejected').length};const delivery=L.matchingDelivery(state.project),jobStatus=state.job?.error||state.job?.status||'';modal('审片清单',`<div class="review-stats"><div><strong>${counts.draft}</strong><span>待判断</span></div><div><strong>${counts.gap}</strong><span>素材缺口</span></div><div><strong>${counts.done}</strong><span>已处理</span></div></div><p>勾选左侧片段，可批量生成实际预览；B-roll 需通过版式检查并由你确认后才能进入成片。未确认的片段保留原口播。</p>${jobStatus?`<p>最近任务：${E(jobStatus)}</p>`:''}${state.run?.error?`<p>Agent 运行提示：${E(state.run.error)}</p>`:''}${state.run?.events?.length?`<details class="desk-trace"><summary>查看 Agent 的检索与取舍记录 · ${state.run.events.length} 步</summary>${state.run.events.map(event=>`<p><b>${E(event.type)}</b> · ${E(event.message)}</p>`).join('')}</details>`:''}<div class="modal-actions"><button class="button ghost" data-desk-action="duplicate">另存制作副本</button><button class="button ghost" data-desk-action="preview">预览所选</button><button class="button primary" data-desk-action="render">渲染已确认片段 ↗</button></div>${delivery?.url?`<p><a href="${E(P.media(delivery.url))}" target="_blank" rel="noopener">打开最新成片 ↗</a></p>`:''}<p><a href="${P.prefix}/projects/${E(state.project.id)}/export" target="_blank" rel="noopener">导出当前制作记录 ↗</a></p>`);}
 let drag=null;
 function install(rootElement){rootElement.addEventListener('click',e=>{const t=e.target.closest('[data-desk-view],[data-desk-select],[data-desk-filter],[data-desk-tab],[data-desk-action],[data-desk-style],[data-desk-seek],[data-desk-use],[data-desk-case]');if(!t||state.busy)return;e.stopPropagation();const task=async()=>{if(t.dataset.deskView){if(t.dataset.deskView==='research'){S.view='replica';history.replaceState({},'',`?${S.p?'project='+S.p.id+'&':''}view=replica`);shell();return;}state.view=t.dataset.deskView;renderView();return;}if(t.dataset.deskSelect){select(t.dataset.deskSelect);return;}if(t.dataset.deskFilter){state.filter=t.dataset.deskFilter;renderView();return;}if(t.dataset.deskTab){state.tab=t.dataset.deskTab;renderView();return;}if(t.dataset.deskStyle){state.styleId=t.dataset.deskStyle;state.edited={};state.tab='edit';renderView();return;}if(t.dataset.deskUse){state.styleId=t.dataset.deskUse;state.edited={};state.view='make';state.tab='edit';renderView();return;}if(t.dataset.deskSeek){seek(Number(t.dataset.deskSeek));return;}if(t.dataset.deskCase){await importCase(t.dataset.deskCase);return;}const c=current();switch(t.dataset.deskAction){case 'clear':state.checked.clear();renderView();break;case 'reject':await batch('reject',selectedIds());break;case 'approve':await doApprove(selectedIds());break;case 'reject-current':await batch('reject',[c.id]);break;case 'approve-current':await doApprove([c.id]);break;case 'edit':state.tab='edit';renderView();break;case 'save-style':await saveStyle();break;case 'generate':await run(state.run?.status==='failed'||state.run?.status==='interrupted'?state.run.id:null);break;case 'new-project':newProject();break;case 'import-current':await importCurrent();break;case 'go-import':S.view='library';history.replaceState({},'',`?view=library`);shell();break;case 'preview':await job('preview',selectedIds().length?selectedIds():[c?.id]);break;case 'render':await job('render');break;case 'review':review();break;case 'close':closeModal();break;case 'cases':await cases();break;case 'images':root()?.querySelector('#desk-images')?.click();break;case 'duplicate':{const result=await client.request(`/projects/${state.project.id}/duplicate`,{});state.projects.unshift(result.project);applyProject(result.project);closeModal();state.message='已新建制作副本；共享样式与素材仍来自同一个库。';renderView();break;}case 'play':{const v=root()?.querySelector('#desk-source-video');if(v)v.paused?await v.play():v.pause();break;}case 'back':seek(state.time-1);break;case 'forward':seek(state.time+1);break;case 'mute':{const v=root()?.querySelector('#desk-source-video');if(v){v.muted=!v.muted;t.textContent=v.muted?'♫ 已静音':'♫ 音频开';}break;}case 'zoom-out':state.zoom=Math.max(1,state.zoom-.25);renderView();break;case 'zoom-in':state.zoom=Math.min(4,state.zoom+.25);renderView();break;}};Promise.resolve().then(task).catch(fail);});
 rootElement.addEventListener('change',e=>{const t=e.target;const task=async()=>{if(t.dataset.deskCheck){t.checked?state.checked.add(t.dataset.deskCheck):state.checked.delete(t.dataset.deskCheck);renderView();}else if(t.hasAttribute('data-desk-check-all')){L.filter(cards(),state.filter).forEach(c=>t.checked?state.checked.add(c.id):state.checked.delete(c.id));renderView();}else if(t.id==='desk-project-select'){const result=await client.request(`/projects/${t.value}`);applyProject(result.project);state.tab='decision';state.edited={};state.styleId=null;state.time=current()?.start||0;state.run=null;state.message='';closeModal();const runId=result.project.runs?.at(-1);if(runId)try{state.run=(await client.request(`/runs/${runId}`)).run;}catch{state.run=null;}renderView();}else if(t.dataset.deskEffect)await effect(t.dataset.deskEffect,t.value);else if(t.id==='desk-images')await uploadImages(t.files);else if(t.dataset.deskField){const field=t.dataset.deskField;if(t.dataset.deskType==='image'){const a=asset(t.value);if(a)state.edited[field]={asset_id:a.id,revision:a.revision};else delete state.edited[field];}else state.edited[field]=t.value;}};Promise.resolve().then(task).catch(fail);});
 rootElement.addEventListener('input',e=>{if(e.target.dataset.deskField&&e.target.dataset.deskType!=='image')state.edited[e.target.dataset.deskField]=e.target.value;});
 rootElement.addEventListener('keydown',e=>{if(e.target.dataset.deskSelect&&(e.key==='Enter'||e.key===' ')){e.preventDefault();select(e.target.dataset.deskSelect);}});
 rootElement.addEventListener('pointerdown',e=>{const clip=e.target.closest('[data-desk-clip]');if(clip){const c=cards().find(x=>x.id===clip.dataset.deskClip);if(!c)return;const track=clip.parentElement.getBoundingClientRect();drag={id:c.id,card:c,edge:e.target.closest('[data-desk-trim]')?.dataset.deskTrim||null,x:e.clientX,width:track.width,moved:false,el:clip};e.preventDefault();return;}const ruler=e.target.closest('[data-desk-ruler]');if(ruler){const box=ruler.getBoundingClientRect();seek((e.clientX-box.left)/box.width*total());}});
 document.addEventListener('pointermove',e=>{if(!drag)return;const shift=(e.clientX-drag.x)/drag.width*total(),c=drag.card;drag.moved||=Math.abs(e.clientX-drag.x)>3;const start=drag.edge==='left'?c.start+shift:drag.edge==='right'?c.start:c.start+shift,end=drag.edge==='left'?c.end:drag.edge==='right'?c.end+shift:c.end+shift;drag.start=Math.round(start*10)/10;drag.end=Math.round(end*10)/10;const left=Math.max(0,Math.min(total(),drag.start));drag.el.style.left=`${left/total()*100}%`;drag.el.style.width=`${Math.max(.4,drag.end-left)/total()*100}%`;});
 document.addEventListener('pointerup',()=>{if(!drag)return;const d=drag;drag=null;if(!root()?.contains(d.el))return;if(!d.moved){select(d.id);return;}if(d.card.decision!=='broll'){note('素材缺口尚不能移动；先选好样式。');renderView();return;}if(!L.within(d.card,d.start,d.end,total(),cards())){note('时间超出原片、短于0.4秒、长于15秒或与其他 B-roll 重叠。');renderView();return;}batch('retime',[d.id],{start:d.start,end:d.end}).catch(fail);});
 }
 function seek(time){state.time=Math.max(0,Math.min(total(),time));const v=root()?.querySelector('#desk-source-video');if(v&&v.readyState>=1)v.currentTime=state.time;updatePlayback();}
 function select(id){const c=cards().find(x=>x.id===id);if(!c)return;state.selected=id;state.styleId=null;state.edited={};state.time=c.start+.25;renderView();}
 function render(){const container=document.querySelector('#content');if(!container)return;container.innerHTML='<div class="ai-workbench-desk"></div>';install(root());hydrate();}
 function open(view){if(!['make','library'].includes(view))return;state.view=view;if(S.view==='ai-making')renderView();}
 return{render,open};
})();
